/* =====================================================
   START PAPER RUN
===================================================== */
export async function startPaperRun(
  req: Request,
  res: Response<ApiResponse<StartPaperRunResponse>>,
  next: NextFunction
) {
  const client = await pool.connect();

  try {
    const payload = StartPaperRunLegacyRequestSchema.parse(req.body);

    const {
      exchange,
      symbol,
      symbols,
      timeframe,
      initial_balance,
      fee_rate,
    } = payload;
    const normalizedSymbols =
      symbols && symbols.length > 0
        ? symbols.map((item) => item.trim().toUpperCase()).filter(Boolean)
        : symbol
            .split(",")
            .map((item) => item.trim().toUpperCase())
            .filter(Boolean);
    if (normalizedSymbols.length === 0) {
      return sendError(res, "At least one symbol is required", 400);
    }
    const symbolValue = normalizedSymbols.join(",");

    const parsedBalance = Number(initial_balance);
    if (!Number.isFinite(parsedBalance) || parsedBalance <= 0) {
      return sendError(res, "Invalid initial_balance", 400);
    }

    const userId = req.user!.id;
    const concurrentRuns = await getConcurrentRunsCount(userId);
    if (concurrentRuns >= 20) {
      return sendError(res, "Maximum concurrent runs reached", 429);
    }

    const algoResult = payload.algorithm_id
      ? await client.query(
          `SELECT id, code
           FROM algorithms
           WHERE id = $1 AND user_id = $2`,
          [payload.algorithm_id, userId]
        )
      : await client.query(
          `SELECT id, code
           FROM algorithms
           WHERE user_id = $1 AND code = $2
           ORDER BY updated_at DESC
           LIMIT 1`,
          [userId, payload.code]
        );

    if (!algoResult.rowCount) {
      return sendError(res, "Algorithm not found", 404);
    }

    const algorithmId: string = algoResult.rows[0].id;
    const code = algoResult.rows[0].code;

    await client.query("BEGIN");

    const runInsert = await client.query(
      `INSERT INTO paper_runs
       (user_id, algorithm_id, exchange, fee_rate,
        symbol, timeframe, initial_balance, current_balance, status)
       VALUES ($1,$2,$3,$4,$5,$6,$7,$7,'ACTIVE')
       RETURNING id`,
      [
        userId,
        algorithmId,
        exchange ?? "binance",
        fee_rate ?? 0.001,
        symbolValue,
        timeframe,
        parsedBalance,
      ]
    );

    const runId: string = runInsert.rows[0].id;
    const runAlgorithmId: string = algorithmId;

    await client.query("COMMIT");

    sendSuccess(res, { run_id: runId }, 201);

    // Start engine asynchronously
    startPaperOnEngine({
      run_id: runId,
      code,
      exchange: exchange ?? "binance",
      symbol: symbolValue,
      symbols: normalizedSymbols,
      timeframe,
      initial_balance: parsedBalance,
      fee_rate: fee_rate ?? 0.001,
    }).catch(async () => {
      unmarkRecoveredPaperRun(runId);
      await pool.query(
        `UPDATE paper_runs SET status = 'STOPPED' WHERE id = $1`,
        [runId]
      );
    });
    markRecoveredPaperRun(runId);
    void recomputeAlgorithmPerformance(runAlgorithmId);

  } catch (err) {
    await client.query("ROLLBACK");
    next(err);
  } finally {
    client.release();
  }
}

/* =====================================================
   STOP PAPER RUN
===================================================== */
export async function stopPaperRun(
  req: Request,
  res: Response<ApiResponse<MessageResponse>>,
  next: NextFunction
) {
  try {
    const rawId = req.params.id;

    if (!rawId || Array.isArray(rawId)) {
      return sendError(res, "Invalid id parameter", 400);
    }

    const runId = rawId;
    const userId = req.user!.id;

    const runResult = await pool.query<{ id: string; algorithm_id: string }>(
      `SELECT id, algorithm_id FROM paper_runs WHERE id = $1 AND user_id = $2`,
      [runId, userId]
    );

    if (!runResult.rowCount) {
      return sendError(res, "Paper run not found", 404);
    }

    try {
      await stopPaperOnEngine(runId);
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      console.warn(
        `[PaperStop] Engine stop failed run_id=${runId} message=${message}. Marking run stopped in backend anyway.`
      );
    }
    unmarkRecoveredPaperRun(runId);

    await pool.query(
      `UPDATE paper_runs
       SET status = 'STOPPED',
           updated_at = NOW()
       WHERE id = $1`,
      [runId]
    );
    void recomputeAlgorithmPerformance(String(runResult.rows[0].algorithm_id));

    return sendSuccess(res, { message: "Paper run stopped" });

  } catch (err) {
    next(err);
  }
}

