) as StrategyParameterKey[];

function createOptimizerParamRow(name: StrategyParameterKey | "" = ""): OptimizerParamRow {
  const definition = name ? STRATEGY_PARAMETERS[name] : null;
  return {
    id: `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
    name,
    min: definition ? formatStrategyParameterNumber(definition.min) : "",
    max: definition ? formatStrategyParameterNumber(definition.max) : "",
    step: definition ? formatStrategyParameterNumber(definition.step) : "",
  };
}

function getErrorMessage(error: unknown, fallback: string) {
  return error instanceof Error ? error.message : fallback;
}

function countDecimals(value: string): number {
  const normalized = value.trim();
  if (!normalized.includes(".")) {
    return 0;
  }

  return normalized.split(".")[1]?.length ?? 0;
}

function buildRangeValues(minRaw: string, maxRaw: string, stepRaw: string): number[] {
  const min = Number(minRaw);
  const max = Number(maxRaw);
  const step = Number(stepRaw);

  if (!Number.isFinite(min) || !Number.isFinite(max) || !Number.isFinite(step)) {
    throw new Error("Optimizer ranges require numeric min, max, and step values.");
  }

  if (step <= 0) {
    throw new Error("Optimizer step must be greater than 0.");
  }

  if (max < min) {
    throw new Error("Optimizer max must be greater than or equal to min.");
  }

  const precision = Math.max(
    countDecimals(minRaw),
    countDecimals(maxRaw),
    countDecimals(stepRaw)
  );
  const epsilon = step / 1_000_000;
  const values: number[] = [];

  for (let index = 0; index < 1000; index += 1) {
    const current = min + step * index;
    if (current > max + epsilon) {
      break;
    }
    values.push(Number(current.toFixed(precision)));
  }

  if (values.length === 0) {
    values.push(Number(min.toFixed(precision)));
  }

  return values;
}

function createOptimizerRowsFromDetectedParams(
  detectedParams: Partial<Record<StrategyParameterKey, number>>
): OptimizerParamRow[] {
  return Object.keys(detectedParams).map((name) =>
    createOptimizerParamRow(name as StrategyParameterKey)
  );
}

function areOptimizerRowsEmpty(rows: OptimizerParamRow[]): boolean {
  return rows.every(
    (row) =>
      !row.name.trim() &&
      !row.min.trim() &&
      !row.max.trim() &&
      !row.step.trim()
  );
}


function classifyMetric(
  name: string,
  value: number
): "good" | "neutral" | "bad" {
  const n = Number.isFinite(value) ? value : 0;
  switch (name) {
    case "sharpe":
      if (n >= 1) return "good";
      if (n >= 0.5) return "neutral";
      return "bad";
    case "sortino":
      if (n >= 1.5) return "good";
      if (n >= 1) return "neutral";
      return "bad";
    case "calmar":
      if (n >= 1) return "good";
      if (n >= 0.5) return "neutral";
      return "bad";
    case "avg_yearly_return":
      if (n >= 20) return "good";
      if (n >= 5) return "neutral";
      return "bad";
    case "win_rate":
      if (n >= 55) return "good";
      if (n >= 45) return "neutral";
      return "bad";
    case "max_drawdown":
      if (n <= 20) return "good";
      if (n <= 40) return "neutral";
      return "bad";
    case "return_stability":
      if (n >= 0.2) return "good";
      if (n >= 0.1) return "neutral";
      return "bad";
    case "confidence_score":
      if (n >= 0.7) return "good";
      if (n >= 0.4) return "neutral";
      return "bad";
    default:
      return "neutral";
  }
}

