async def emit_event(run_id: str, event_type: str, payload: Dict[str, Any]) -> None:
    """
    Sends an event to the backend (DB persistence + websocket broadcast).
    """
    event_data = {
        "run_id": run_id,
        "event_type": event_type,
        "payload": payload,
    }

    try:
        client = _get_http_client()
        resp = await client.post(BACKEND_EVENT_URL, json=event_data)

        if resp.status_code >= 400:
            logger.error(
                "[PaperTrading][%s] Backend rejected event=%s status=%s body=%s",
                run_id,
                event_type,
                resp.status_code,
                resp.text[:300],
            )
    except Exception as e:
        logger.error("[PaperTrading][%s] Failed to emit event=%s err=%s", run_id, event_type, e)


# ======================================================
# CONTEXT ADAPTER (BACKWARD COMPAT)
# ======================================================

def _adapt_context_for_strategies(ctx: Dict[str, Any]) -> Dict[str, Any]:
    """
    Your canonical context is:
      {
        "candle": {...},
        "history": (...),
        "indicators": {...},
        ...
      }

    But some strategies may do ctx["close"] instead of ctx["candle"]["close"].
    To prevent random KeyError crashes, we keep the canonical structure and ALSO
    inject top-level candle keys for backward compatibility.
    """
    candle = ctx.get("candle") or {}
    if isinstance(candle, dict):
        for k in ("open", "high", "low", "close", "volume", "timestamp"):
            if k in candle and k not in ctx:
                ctx[k] = candle[k]
    return ctx


def _safe_intent(raw_signal: Any) -> str:
    if raw_signal is None:
        return "HOLD"
    return str(raw_signal).upper().strip()


def _normalize_signal(raw_signal: Any) -> str:
    if raw_signal is None:
        return "HOLD"
    s = str(raw_signal).upper().strip()
    if s in {"LONG", "BUY"}:
        return "BUY"
    if s in {"SHORT", "SELL", "CLOSE"}:
        return "SELL"
    return "HOLD"


def _normalize_order_instruction(raw_signal: Any) -> Optional[Dict[str, Any]]:
    if not isinstance(raw_signal, dict):
        return None

    action = str(raw_signal.get("action", "")).upper().strip()
    if action not in ("BUY", "SELL", "CLOSE", "HOLD"):
        return None
    if action == "HOLD":
        return None

    order_type = str(raw_signal.get("order_type", "market")).lower().strip()
    if order_type not in ("market", "limit", "stop", "stop_limit"):
        order_type = "market"

    return {
        "action": action,
        "order_type": order_type,
        "price": raw_signal.get("price"),
        "stop_price": raw_signal.get("stop_price"),
        "size_pct": raw_signal.get("size_pct"),
        "quantity": raw_signal.get("quantity"),
        "reduce_only": bool(raw_signal.get("reduce_only", action in ("SELL", "CLOSE"))),
    }


# ======================================================
# PAPER SESSION
# ======================================================

class PaperSession:
    """
    One paper trading session (many can run simultaneously).
    """

    def __init__(self, request):
        self.run_id = request.run_id
        self.exchange = request.exchange
        raw_symbols = getattr(request, "symbols", None)
        if raw_symbols and isinstance(raw_symbols, list):
            parsed_symbols = [str(item).upper() for item in raw_symbols if str(item).strip()]
        else:
            parsed_symbols = [
                part.strip().upper()
                for part in str(request.symbol).split(",")
                if part.strip()
            ]
        if not parsed_symbols:
            parsed_symbols = [str(request.symbol).upper()]

        seen: set[str] = set()
        self.symbols: List[str] = []
        for item in parsed_symbols:
            if item not in seen:
                seen.add(item)
                self.symbols.append(item)

        self.symbol = self.symbols[0]
        self.primary_symbol = self.symbol
        self.timeframe = request.timeframe

        # Account model (spot-like)
        self.initial_balance = float(request.initial_balance)
        self.quote_balance = float(request.initial_balance)  # e.g. USDT in BTCUSDT
        self.base_balance = 0.0                              # e.g. BTC in BTCUSDT
        self.last_price: Optional[float] = None

        metadata_client = None
        try:
            metadata_client = ExchangeFactory.create(
                exchange=self.exchange,
                api_key=request.api_key,
                api_secret=request.api_secret,
                testnet=request.testnet,
            )
        except Exception:
            logger.exception(
                "[PaperTrading][%s] Failed creating exchange client for metadata.",
                self.run_id,
            )

        if request.fee_rate is not None:
            self.fee_rate = float(request.fee_rate)
        else:
            try:
                if metadata_client is not None:
                    self.fee_rate = float(metadata_client.get_fee_model(self.symbol).taker_fee)
                else:
                    self.fee_rate = 0.001
            except Exception:
                logger.exception(
                    "[PaperTrading][%s] Failed to load exchange fee model; using fallback taker fee.",
                    self.run_id,
                )
                self.fee_rate = 0.001

        self.symbol_lot_sizes: Dict[str, Optional[float]] = {}
        self.symbol_tick_sizes: Dict[str, Optional[float]] = {}
        for symbol_item in self.symbols:
            lot_size: Optional[float] = None
            tick_size: Optional[float] = None
            if metadata_client is not None:
                try:
                    raw_lot_size = metadata_client.get_lot_size(symbol_item)
                    if raw_lot_size is not None and float(raw_lot_size) > 0:
                        lot_size = float(raw_lot_size)
                    raw_tick_size = metadata_client.get_tick_size(symbol_item)
                    if raw_tick_size is not None and float(raw_tick_size) > 0:
                        tick_size = float(raw_tick_size)
                except Exception:
                    logger.warning(
                        "[PaperTrading][%s] Failed to load lot/tick size for %s",
                        self.run_id,
                        symbol_item,
                        exc_info=True,
                    )
            self.symbol_lot_sizes[symbol_item] = lot_size
            self.symbol_tick_sizes[symbol_item] = tick_size

        self.position: Optional[Dict[str, Any]] = None
        self.positions: Dict[str, Dict[str, Any]] = {}
        self.pending_orders_by_symbol: Dict[str, List[Dict[str, Any]]] = {
            symbol: [] for symbol in self.symbols
        }
        self.pending_orders: List[Dict[str, Any]] = self.pending_orders_by_symbol[self.primary_symbol]
        self.trades: List[Dict[str, Any]] = []
        self.candles_by_symbol: Dict[str, List[Dict[str, Any]]] = {
            symbol: [] for symbol in self.symbols
        }
        self.candles: List[Dict[str, Any]] = self.candles_by_symbol[self.primary_symbol]
        self.last_prices: Dict[str, float] = {}
        self.realized_pnl = 0.0
        self.equity_curve: List[Dict[str, float]] = []
        self.portfolio = PortfolioEngine(initial_cash=self.initial_balance)

import { z } from "zod";
import { BacktestRunSchema } from "./backtest";
import { PaperRunSchema } from "./paper";

/* =========================
   Algorithm Entity
========================= */

export const AlgorithmSchema = z.object({
  id: z.string().uuid(),
  user_id: z.string().uuid().optional(),
  username: z.string().nullable().optional(),
  name: z.string(),
  notes_html: z.string().nullable().optional(),
  code: z.string(),
  github_url: z.string().nullable().optional(),
  is_public: z.boolean().optional(),
  performance_score: z.number().optional(),
  avg_return_percent: z.number().optional(),
  avg_sharpe: z.number().optional(),
  avg_pnl: z.number().optional(),
  win_rate: z.number().optional(),
  max_drawdown: z.number().optional(),
  runs_count: z.number().optional(),
  calmar_ratio: z.number().optional(),
  sortino_ratio: z.number().optional(),
  return_stability: z.number().optional(),
  confidence_score: z.number().optional(),
  created_at: z.string(),
  updated_at: z.string(),
});

export type Algorithm = z.infer<typeof AlgorithmSchema>;

/* =========================
   DTOs
========================= */

export const CreateAlgorithmSchema = z.object({
  name: z.string().min(1),
  notes_html: z.string().optional(),
  code: z.string().optional(),
  githubUrl: z.string().optional(),
  is_public: z.boolean().optional(),
});

export type CreateAlgorithmDto = z.infer<typeof CreateAlgorithmSchema>;

export const UpdateAlgorithmSchema = z.object({
  name: z.string().optional(),
  notes_html: z.string().optional(),
  code: z.string().optional(),
  is_public: z.boolean().optional(),
});

export type UpdateAlgorithmDto = z.infer<typeof UpdateAlgorithmSchema>;

/* =========================
   Responses
========================= */

export const AlgorithmsListResponseSchema = z.object({
  algorithms: z.array(AlgorithmSchema),
});

export type AlgorithmsListResponse = z.infer<
  typeof AlgorithmsListResponseSchema
>;

export const AlgorithmSummarySchema = z.object({
  id: z.string().uuid(),
  name: z.string(),
  performance_score: z.number(),
  avg_return_percent: z.number(),
  avg_sharpe: z.number(),
  max_drawdown: z.number(),
  runs_count: z.number(),
  user_id: z.string().uuid(),
  username: z.string().nullable(),
  is_public: z.boolean(),
});

export type AlgorithmSummary = z.infer<typeof AlgorithmSummarySchema>;

export const AlgorithmRankingResponseSchema = z.object({
  algorithms: z.array(AlgorithmSummarySchema),
});

export type AlgorithmRankingResponse = z.infer<
  typeof AlgorithmRankingResponseSchema
>;

export const PublicProfileResponseSchema = z.object({
  username: z.string(),
  algorithms: z.array(AlgorithmSummarySchema),
});

export type PublicProfileResponse = z.infer<typeof PublicProfileResponseSchema>;

export const AlgorithmBacktestRunSchema = BacktestRunSchema.pick({
  id: true,
  symbol: true,
  exchange: true,
  timeframe: true,
  status: true,
  created_at: true,
  start_date: true,
  end_date: true,
  initial_balance: true,
  fee_rate: true,
  total_return_percent: true,
  total_return_usdt: true,
  sharpe_ratio: true,
}).extend({
  exchange: z.string().optional(),
  sharpe_ratio: z.number().nullable().optional(),
});

export type AlgorithmBacktestRun = z.infer<typeof AlgorithmBacktestRunSchema>;

export const AlgorithmPaperRunSchema = PaperRunSchema.pick({
  id: true,
  exchange: true,
  symbol: true,
  timeframe: true,
  status: true,
  initial_balance: true,
  current_balance: true,
  quote_balance: true,
  base_balance: true,
  equity: true,
  last_price: true,
  started_at: true,
  pnl: true,
  win_rate_percent: true,
});

export type AlgorithmPaperRun = z.infer<typeof AlgorithmPaperRunSchema>;

export const AlgorithmRunsResponseSchema = z.object({
  backtests: z.array(AlgorithmBacktestRunSchema),
  paperRuns: z.array(AlgorithmPaperRunSchema),
});

export type AlgorithmRunsResponse = z.infer<typeof AlgorithmRunsResponseSchema>;
